export function diagnosticReport({secure,recognition,microphone,service,lastError}){return ['Liquid Lens · Ses bağlantı raporu','HTTPS: '+(secure?'evet':'hayır'),'Ses tanıma API: '+(recognition?'var':'yok'),'Mikrofon izni: '+microphone,'Servis durumu: '+service,'Son hata: '+(lastError?.code||'yok'),lastError?'Aşama: '+lastError.phase+'\nZaman: '+lastError.at:''].filter(Boolean).join('\n');}
export function serviceLabel(state,available){if(!available)return 'Ses tanıma API’si yok';return ({untried:'API var · Servis henüz denenmedi',connecting:'Ses tanıma bağlantısı kuruluyor…',listening:'Ses tanıma dinlemeyi başlattı',recognized:'Son denemede metin algılandı',failed:'Ses tanıma denemesi başarısız',stopped:'Dinleme durduruldu'})[state]||'Servis henüz denenmedi';}
